import{ht as e,nt as t,o as n,tt as r}from"./chunks/framework.CuG1B4CC.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Global metagenomic resources hold transformative potential for the life sciences, yet remain vastly underutilized because scalable and sensitive sequence similarity search remains challenging. Existing approaches rely largely on descriptive metadata or exact matching of short sequence fragments, limiting their ability to identify homologous sequences across datasets.</p><p>Meshmetal employs deep metric learning to encode genomic sequences into similarity-preserving binary hash codes, enabling efficient sequence comparison in Hamming space. Meshmetal indexed petabase-scale metagenomic data while supporting accurate, rapid and storage-efficient sequence similarity search. Importantly, the index architecture is highly scalable with new metagenomic datasets without requiring reconstruction. In benchmarks, Meshmetal achieved more than 50% higher retrieval accuracy than competing methods for homologous queries. Applications to identify HKU5-CoV virus and mobilized colistin resistance genes, recovering up to 3167% more related metagenomic datasets, further demonstrated its capacity of similarity search, thereby facilitating downstream biological discovery and surveillance.</p><h2 id="key-system-components" tabindex="-1">Key System Components <a class="header-anchor" href="#key-system-components" aria-label="Permalink to “Key System Components”">​</a></h2><ol><li><strong><code>DML</code></strong>: Deep Metric Learning Transformer model training and architecture.</li><li><strong><code>encoding</code></strong>: High-throughput GPU/CPU sequence download and embedding pipeline.</li><li><strong><code>build_index</code></strong>: C++ tools for parallel hash deduplication, set combination, and sparse matrix annotation vector generation.</li><li><strong><code>BRWT</code></strong>: Binary Relation Wavelet Tree for ultra-dense compression of sample-to-hash annotation matrices.</li><li><strong><code>standalone_faiss</code></strong>: Custom C++ 128-bit binary hash index supporting memory mapping (<code>mmap</code>) and REST API servers.</li></ol>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};